/**
 * Search, on `src/api/schema.d.ts` — generated by `make types` from the real
 * pydantic models and held to the tree by `make lint-generated` (contract C9).
 *
 * Do NOT hand-declare these shapes. A local `BriefSummary` here SHADOWS the
 * differently-shaped one in `types/brief.ts`, so importing from that module into
 * `SearchView` silently resolves to whichever declaration wins -- and a
 * hand-written shape drifts from the server besides (`types/curation.ts` records
 * `DefinitionQueue` missing `decided` that way).
 *
 * The brief-side shapes are not restated here; the view imports them from
 * `types/brief.ts`.
 */

import type { components } from '@/api/schema'

type Schemas = components['schemas']

/**
 * One entity in a search result.
 *
 * NOTE the optionality: `type` and `status` are `string | null` on the model,
 * not required strings, so the Chip rendering `hit.type` has to tolerate an
 * entity with no type -- a real state, since an entity is minted before it is
 * classified.
 */
export type EntityHit = Schemas['EntityHit']

/** `GET /search`. `entities` is optional on the model, so the view's existing
 *  `?? []` is load-bearing rather than defensive. */
export type EntitySearchResults = Schemas['EntitySearchResults']

/**
 * `GET /graph/search` — a different shape from `EntityHit`, deliberately. It
 * carries `degree`, `score` and `mention_count` because "a name alone does not
 * tell you which `Lattice` you meant". `GraphSearch` and `CommandPalette` read
 * this one.
 */
export type EntitySearchHit = Schemas['EntitySearchHit']
